(7524277, 1202518, 185757, '<td valign="top">Nicely visioned and executed. A top 3 pick for me.</td>', 'Nicely visioned and executed. A top 3 pick for me.', '2017-07-19 03:53:11.000000', NULL, 1),
(7524302, 1202525, 173844, '<td valign="top">Lines, lines, lines, but they seem more woven according to arcane structural rules than awkwardly haphazard.  Amidst it all, the serenity of the woman at the table.  A co-favorite.</td>', 'Lines, lines, lines, but they seem more woven according to arcane structural rules than awkwardly haphazard.  Amidst it all, the serenity of the woman at the table.  A co-favorite.', '2017-07-19 12:50:23.000000', NULL, 1),
(7524304, 1202587, 173844, '<td valign="top">The bird''s abiding attentiveness is reassuring in this chop-chop world.  The disposition of the fruit on the left is pleasantly decorative.  The sky is allowed room to express itself.  The muted palette is lovely.  A co-favorite.</td>', 'The bird''s abiding attentiveness is reassuring in this chop-chop world.  The disposition of the fruit on the left is pleasantly decorative.  The sky is allowed room to express itself.  The muted palette is lovely.  A co-favorite.', '2017-07-19 13:03:50.000000', NULL, 1),
(7524306, 1202518, 173844, '<td valign="top">Graphically, impressively simple.  Nice mood in this sci-fi dream snippet.</td>', 'Graphically, impressively simple.  Nice mood in this sci-fi dream snippet.', '2017-07-19 13:07:51.000000', NULL, 1),
(7524310, 1202581, 173844, '<td valign="top">Complex, varied symmetry invites one to wander throughout this amazing library.  However, it''s the optically playful arched ceiling that most commands attention. Beautifully photographed.</td>', 'Complex, varied symmetry invites one to wander throughout this amazing library.  However, it''s the optically playful arched ceiling that most commands attention. Beautifully photographed.', '2017-07-19 13:33:17.000000', NULL, 1),
(7524311, 1202526, 173844, '<td valign="top">Perfectly lit to do justice to this majestic playland.  Velvet delicacy.  Beautiful.</td>', 'Perfectly lit to do justice to this majestic playland.  Velvet delicacy.  Beautiful.', '2017-07-19 13:38:57.000000', NULL, 1),
(7524312, 1202537, 173844, '<td valign="top">Cleverly angled to the diagonal to most fully convey the powerful shaft of light pouring into the stunning interior.  The composition is elegantly balanced.</td>', 'Cleverly angled to the diagonal to most fully convey the powerful shaft of light pouring into the stunning interior.  The composition is elegantly balanced.', '2017-07-19 13:42:56.000000', NULL, 1),
(7524313, 1202597, 173844, '<td valign="top">Has the feel of a Victorian storybook.  Well done.  The lovely background, so very apart from the foreground tragic drama, seems a moral commentary on  fragility and dispassion.  Or maybe not, just my impression.  This could be one of a compelling series.</td>', 'Has the feel of a Victorian storybook.  Well done.  The lovely background, so very apart from the foreground tragic drama, seems a moral commentary on  fragility and dispassion.  Or maybe not, just my impression.  This could be one of a compelling series.', '2017-07-19 13:56:18.000000', NULL, 1),
(7524314, 1202568, 173844, '<td valign="top">Inviting entryway to a story.  I like how the bridge is positioned and how the  menace of the spider is foreshadowed in the lowering sky.  Evocative.</td>', 'Inviting entryway to a story.  I like how the bridge is positioned and how the  menace of the spider is foreshadowed in the lowering sky.  Evocative.', '2017-07-19 14:03:15.000000', NULL, 1),
(7524317, 1202467, 173844, '<td valign="top">Well done and surprising, with such a sharp entry into the peaceful, expansive landscape.  It''s subliminally shocking how similar the fuselage is to the underside of a crustacean.</td>', 'Well done and surprising, with such a sharp entry into the peaceful, expansive landscape.  It''s subliminally shocking how similar the fuselage is to the underside of a crustacean.', '2017-07-19 14:10:34.000000', NULL, 1),
(7524318, 1202315, 173844, '<td valign="top">What a great find.  Draws you right in, without a simple exit.</td>', 'What a great find.  Draws you right in, without a simple exit.', '2017-07-19 14:13:58.000000', NULL, 1),
(7524319, 1202565, 173844, '<td valign="top">Amazing landscape.</td>', 'Amazing landscape.', '2017-07-19 14:14:48.000000', NULL, 1),
(7524323, 1202572, 173844, '<td valign="top">I''m enjoying this well-composed, understated everyday moment.  Only when you examine this a bit do you see that the man is in what may very well be a gurney.  It resonates more than any straightforward depiction can.</td>', 'I''m enjoying this well-composed, understated everyday moment.  Only when you examine this a bit do you see that the man is in what may very well be a gurney.  It resonates more than any straightforward depiction can.', '2017-07-19 14:25:14.000000', NULL, 1),
